// Provides the desktop launcher interface.
using System;using System.Diagnostics;using System.Drawing;using System.IO;using System.Threading.Tasks;using System.Windows.Forms;
static class Program {
 [STAThread]static void Main(string[] args){if(args.Length>0&&args[0]=="--self-test"){Injector.SelfTest();return;}Application.EnableVisualStyles();Application.Run(new ToolForm());}
}
sealed class ToolForm:Form {
 Label status;Button load,unload;bool busy;
 public ToolForm(){Text="SP-KNPP Reloader";ClientSize=new Size(580,350);MinimumSize=Size;MaximumSize=Size;StartPosition=FormStartPosition.CenterScreen;BackColor=Color.FromArgb(17,21,29);ForeColor=Color.White;Font=new Font("Segoe UI",10);var title=new Label{Text="SP-KNPP Reloader",Font=new Font("Segoe UI",23,FontStyle.Bold),AutoSize=true,Location=new Point(28,25)};Controls.Add(title);var description=new Label{Text="Reload and apply custom car-part packs\nin single-player, training and multiplayer.",AutoSize=true,Location=new Point(30,84)};Controls.Add(description);status=new Label{Text="Requires Kino 3.39.1.\nStart CarX, wait for Kino, then load the tool.",Location=new Point(30,148),Size=new Size(520,85)};Controls.Add(status);load=new Button{Text="Launch CarX & load tool",Location=new Point(30,242),Size=new Size(330,46),FlatStyle=FlatStyle.Flat,BackColor=Color.FromArgb(54,102,160)};unload=new Button{Text="Unload tool",Location=new Point(375,242),Size=new Size(175,46),FlatStyle=FlatStyle.Flat};Controls.Add(load);Controls.Add(unload);Controls.Add(new Label{Text="F7  MENU     /     F9  UNLOAD",AutoSize=true,Location=new Point(30,311)});load.Click+=async delegate{await Run(false);};unload.Click+=async delegate{await Run(true);};FormClosing+=delegate(object s,FormClosingEventArgs e){if(busy)e.Cancel=true;};}
 async Task Run(bool remove){if(busy)return;busy=true;load.Enabled=unload.Enabled=false;try{if(!remove){if(!File.Exists(Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"SP-KNPP.Mod.dll")))throw new Exception("Keep SP-KNPP.Mod.dll beside the launcher.");var processes=Process.GetProcessesByName("Drift Racing Online");bool running=processes.Length>0;foreach(var p in processes)p.Dispose();if(!running){Process.Start(new ProcessStartInfo("steam://rungameid/635260"){UseShellExecute=true});status.Text="Starting CarX through Steam. Complete any Steam prompts.";DateTime deadline=DateTime.UtcNow.AddMinutes(5);bool ready=false;while(DateTime.UtcNow<deadline){await Task.Delay(1000);var ps=Process.GetProcessesByName("Drift Racing Online");foreach(var p in ps){using(p){if(p.MainWindowHandle!=IntPtr.Zero)ready=true;}}if(ready)break;}if(!ready)throw new Exception("CarX did not open. Start it through Steam and retry.");await Task.Delay(8000);}}status.Text="Connecting to CarX…";string result=await Task.Run(()=>Injector.Inject(remove));status.Text=remove?"Unload requested. Return to CarX to complete it.":"Loaded. Return to CarX and press F7.\nWait for Kino and your car before reloading packs.";}catch(Exception e){status.Text=e.GetBaseException().Message;}finally{busy=false;load.Enabled=unload.Enabled=true;}}
}
